/* Blockly 10.4.3 custom blocks for thesada visual rules. */
var ThesadaRules = (function () {
  "use strict";

  var PREAMBLE = [
    "-- generated by thesada visual rules editor",
    "-- SPDX-License-Identifier: GPL-3.0-only",
    "",
    'Log.info("rules.lua loaded")',
    "",
    'local prefix = Config.get("mqtt.topic_prefix") or "thesada/node"',
    'local unit   = Config.get("temperature.unit") or "C"',
    "",
    "local sustain = {}",
    "local cooldown = {}",
    "local COOLDOWN_MS = 900000",
    "local TEMP_SUSTAIN = 5",
    "local TEMP_SUSTAIN_MS = 300000",
    "local PUMP_SUSTAIN = 5",
    "",
    "local function can_alert(key)",
    "  local now = Node.uptime()",
    "  if cooldown[key] and (now - cooldown[key]) < COOLDOWN_MS then",
    "    return false",
    "  end",
    "  return true",
    "end",
    "",
    "local function set_cooldown(key)",
    "  cooldown[key] = Node.uptime()",
    "end",
    "",
    "-- Method calls only: string, table and math are not tables in the device Lua.",
    "-- 255 B fits the device MQTT offline queue slot.",
    "local ALERT_MAX = 255",
    "local CODE_MAX = 64",
    "",
    "-- JSON string body of s in at most max bytes, whole characters. NUL is dropped.",
    "local function json_body(s, max)",
    "  local used, full = 0, false",
    '  return (tostring(s):gsub(".[\\128-\\191]*", function(ch)',
    "    local b, e = ch:byte(), ch",
    '    if b == 0 then e = ch:sub(2)',
    '    elseif b == 34 or b == 92 then e = "\\\\" .. ch',
    "    elseif b < 32 or b == 127 then e = ([[\\u%04x]]):format(b) .. ch:sub(2) end",
    '    if full or used + #e > max then full = true return "" end',
    "    used = used + #e",
    "    return e",
    "  end))",
    "end",
    "",
    "local function alert_json(key, msg)",
    '  local fmt = [[{"severity":"warn","code":"%s","message":"%s"}]]',
    "  local code = json_body(key, CODE_MAX)",
    '  local room = ALERT_MAX - #(fmt:format(code, ""))',
    "  return fmt:format(code, json_body(msg, room))",
    "end",
    "",
    "local function notify(msg, key)",
    "  Log.warn(msg)",
    "  local ok = true",
    "  if Telegram and Telegram.broadcast then",
    "    ok = Telegram.broadcast(msg)",
    "  end",
    '  MQTT.publish(prefix .. "/alert", alert_json(key, msg))',
    "  if ok then set_cooldown(key) end",
    "end",
    "",
    "local temp_sustain_start = {}",
    "",
    "local function temp_sustained(key)",
    "  local now = Node.uptime()",
    "  sustain[key] = (sustain[key] or 0) + 1",
    "  if not temp_sustain_start[key] then temp_sustain_start[key] = now end",
    "  local elapsed = now - temp_sustain_start[key]",
    "  if sustain[key] >= TEMP_SUSTAIN or elapsed >= TEMP_SUSTAIN_MS then",
    "    sustain[key] = 0",
    "    temp_sustain_start[key] = nil",
    "    return can_alert(key)",
    "  end",
    "  return false",
    "end",
    "",
    "local function temp_clear(key)",
    "  sustain[key] = 0",
    "  temp_sustain_start[key] = nil",
    "end",
    "",
    "-- One reading of a sustained rule. Below threshold or stale ends the streak,",
    "-- and so does a silent gap past 5 min or 3 of the shortest gaps seen.",
    "local temp_seen, temp_gap = {}, {}",
    "local function temp_streak(key, over)",
    "  local now, last = Node.uptime(), temp_seen[key]",
    "  if last then",
    "    local g, limit = now - last, TEMP_SUSTAIN_MS",
    "    if temp_gap[key] and 3 * temp_gap[key] > limit then limit = 3 * temp_gap[key] end",
    "    if g > limit then temp_clear(key) end",
    "    if not temp_gap[key] or g < temp_gap[key] then temp_gap[key] = g end",
    "  end",
    "  temp_seen[key] = now",
    "  if over then return temp_sustained(key) end",
    "  temp_clear(key)",
    "  return false",
    "end",
    "",
  ].join("\n");

  function esc(s) {
    return String(s).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  }

  function defineBlocks() {
    Blockly.Blocks["thesada_rules_root"] = {
      init: function () {
        this.appendDummyInput().appendField("rules.lua");
        this.appendStatementInput("BODY").setCheck("ThesadaEvent");
        this.setColour(230);
        this.setTooltip("Top-level rules file");
      },
    };
    Blockly.Lua["thesada_rules_root"] = function (block) {
      return Blockly.Lua.statementToCode(block, "BODY") || "";
    };

    Blockly.Blocks["thesada_on_sensor"] = {
      init: function () {
        this.appendDummyInput()
          .appendField("when")
          .appendField(
            new Blockly.FieldDropdown([
              ["temperature", "temperature"],
              ["current", "current"],
              ["battery", "battery"],
            ]),
            "EVENT"
          )
          .appendField("updates");
        this.appendStatementInput("DO").setCheck("ThesadaCondition");
        this.setPreviousStatement(true, "ThesadaEvent");
        this.setNextStatement(true, "ThesadaEvent");
        this.setColour(20);
      },
    };
    Blockly.Lua["thesada_on_sensor"] = function (block) {
      var event = block.getFieldValue("EVENT");
      var branch = Blockly.Lua.statementToCode(block, "DO") || "";
      var guard =
        event === "temperature"
          ? "  if not data.sensors then return end\n"
          : event === "current"
            ? "  if not data.channels then return end\n"
            : "  if not data.present then return end\n";
      return (
        'EventBus.subscribe("' +
        event +
        '", function(data)\n' +
        guard +
        branch +
        "end)\n"
      );
    };

    Blockly.Blocks["thesada_if_temp"] = {
      init: function () {
        this.appendDummyInput()
          .appendField("if sensor")
          .appendField(new Blockly.FieldTextInput("supply"), "SENSOR")
          .appendField(
            new Blockly.FieldDropdown([
              ["≥", ">="],
              ["≤", "<="],
            ]),
            "OP"
          )
          .appendField(new Blockly.FieldNumber(85, -100, 500, 0.1), "THRESH")
          .appendField("°C");
        this.appendDummyInput()
          .appendField("sustain")
          .appendField(
            new Blockly.FieldDropdown([
              ["yes", "YES"],
              ["no", "NO"],
            ]),
            "SUSTAIN"
          );
        this.appendStatementInput("DO").setCheck([
          "ThesadaTempAction",
          "ThesadaAction",
        ]);
        this.setPreviousStatement(true, "ThesadaCondition");
        this.setNextStatement(true, "ThesadaCondition");
        this.setColour(210);
        this.setTooltip(
          "Named temperature threshold. Sustain fires after 5 readings or 5 min over it. A stale or lower reading, or a long gap with no reading, restarts the count"
        );
      },
    };
    Blockly.Lua["thesada_if_temp"] = function (block) {
      var sensor = esc(block.getFieldValue("SENSOR"));
      var op = block.getFieldValue("OP");
      var thresh = Number(block.getFieldValue("THRESH"));
      var sustain = block.getFieldValue("SUSTAIN") === "YES";
      var branch = Blockly.Lua.statementToCode(block, "DO") || "";
      var keyLit = "temp:" + sensor + ":" + op + thresh;
      if (sustain) {
        return (
          "for _, s in ipairs(data.sensors) do\n" +
          '  if s.name == "' +
          sensor +
          '" then\n' +
          '    local key = "' +
          keyLit +
          '"\n' +
          "    if temp_streak(key, s.temp_c ~= nil and s.temp_c " +
          op +
          " " +
          thresh +
          ") then\n" +
          branch +
          "    end\n" +
          "  end\n" +
          "end\n"
        );
      }
      return (
        "for _, s in ipairs(data.sensors) do\n" +
        '  if s.name == "' +
        sensor +
        '" and s.temp_c ~= nil and s.temp_c ' +
        op +
        " " +
        thresh +
        " then\n" +
        '    local key = "' +
        keyLit +
        '"\n' +
        "    if can_alert(key) then\n" +
        branch +
        "    end\n" +
        "  end\n" +
        "end\n"
      );
    };

    Blockly.Blocks["thesada_if_current"] = {
      init: function () {
        this.appendDummyInput()
          .appendField("if channel")
          .appendField(new Blockly.FieldTextInput("pump"), "CHANNEL")
          .appendField(
            new Blockly.FieldDropdown([
              ["≤", "<="],
              ["≥", ">="],
            ]),
            "OP"
          )
          .appendField(new Blockly.FieldNumber(0.5, 0, 100, 0.1), "THRESH")
          .appendField("A for")
          .appendField(new Blockly.FieldNumber(5, 1, 60, 1), "COUNT")
          .appendField("readings");
        this.appendStatementInput("DO").setCheck("ThesadaAction");
        this.setPreviousStatement(true, "ThesadaCondition");
        this.setNextStatement(true, "ThesadaCondition");
        this.setColour(160);
      },
    };
    Blockly.Lua["thesada_if_current"] = function (block) {
      var ch = esc(block.getFieldValue("CHANNEL"));
      var op = block.getFieldValue("OP");
      var thresh = Number(block.getFieldValue("THRESH"));
      var count = Number(block.getFieldValue("COUNT")) || 5;
      var branch = Blockly.Lua.statementToCode(block, "DO") || "";
      var keyLit = "current:" + ch + ":" + op + thresh + ":" + count;
      return (
        "for _, ch in ipairs(data.channels) do\n" +
        '  if ch.name == "' +
        ch +
        '" then\n' +
        '    local key = "' +
        keyLit +
        '"\n' +
        "    if ch.current_a ~= nil and ch.current_a " +
        op +
        " " +
        thresh +
        " then\n" +
        "      sustain[key] = (sustain[key] or 0) + 1\n" +
        "      if sustain[key] >= " +
        count +
        " and can_alert(key) then\n" +
        branch +
        "        sustain[key] = 0\n" +
        "      end\n" +
        "    else\n" +
        "      sustain[key] = 0\n" +
        "    end\n" +
        "  end\n" +
        "end\n"
      );
    };

    Blockly.Blocks["thesada_if_battery"] = {
      init: function () {
        this.appendDummyInput()
          .appendField("if battery ≤")
          .appendField(new Blockly.FieldNumber(20, 0, 100, 1), "PCT")
          .appendField("% and not charging");
        this.appendStatementInput("DO").setCheck("ThesadaAction");
        this.setPreviousStatement(true, "ThesadaCondition");
        this.setNextStatement(true, "ThesadaCondition");
        this.setColour(45);
      },
    };
    Blockly.Lua["thesada_if_battery"] = function (block) {
      var pct = Number(block.getFieldValue("PCT"));
      var branch = Blockly.Lua.statementToCode(block, "DO") || "";
      return (
        "do\n" +
        "  local pct = data.percent or -1\n" +
        "  if pct >= 0 and pct <= " +
        pct +
        " and not data.charging then\n" +
        '    local key = "battery_low"\n' +
        "    if can_alert(key) then\n" +
        branch +
        "    end\n" +
        "  end\n" +
        "end\n"
      );
    };

    Blockly.Blocks["thesada_notify"] = {
      init: function () {
        this.appendDummyInput()
          .appendField("notify")
          .appendField(new Blockly.FieldTextInput("alert"), "MSG");
        this.setPreviousStatement(true, "ThesadaAction");
        this.setNextStatement(true, "ThesadaAction");
        this.setColour(0);
        this.setTooltip(
          "Log + Telegram + MQTT alert; uses enclosing condition key for cooldown"
        );
      },
    };
    Blockly.Lua["thesada_notify"] = function (block) {
      // Ambient `key` from the enclosing condition (same as can_alert/set_cooldown).
      return 'notify("' + esc(block.getFieldValue("MSG")) + '", key)\n';
    };

    Blockly.Blocks["thesada_notify_temp"] = {
      init: function () {
        this.appendDummyInput()
          .appendField("notify sensor reading +")
          .appendField(new Blockly.FieldTextInput("Overheat!"), "SUFFIX");
        this.setPreviousStatement(true, "ThesadaTempAction");
        this.setNextStatement(true, ["ThesadaTempAction", "ThesadaAction"]);
        this.setColour(0);
        this.setTooltip(
          "Uses s.name / s.temp_c from the temperature loop; converts to Config unit"
        );
      },
    };
    Blockly.Lua["thesada_notify_temp"] = function (block) {
      var suffix = esc(block.getFieldValue("SUFFIX"));
      return (
        'local t = (unit == "F") and (s.temp_c * 9 / 5 + 32) or s.temp_c\n' +
        'notify(s.name .. ": " .. t .. unit .. " - ' +
        suffix +
        '", key)\n'
      );
    };

    // Keep old block id working if a saved workspace used it
    Blockly.Blocks["thesada_if_above"] = Blockly.Blocks["thesada_if_temp"];
    Blockly.Lua["thesada_if_above"] = Blockly.Lua["thesada_if_temp"];
  }

  function seedWorkspace(workspace) {
    var root = workspace.newBlock("thesada_rules_root");
    root.initSvg();
    root.render();
    root.moveBy(24, 24);

    var onTemp = workspace.newBlock("thesada_on_sensor");
    onTemp.setFieldValue("temperature", "EVENT");
    onTemp.initSvg();
    onTemp.render();
    root.getInput("BODY").connection.connect(onTemp.previousConnection);

    var ifHot = workspace.newBlock("thesada_if_temp");
    ifHot.setFieldValue("supply", "SENSOR");
    ifHot.setFieldValue(">=", "OP");
    ifHot.setFieldValue("85", "THRESH");
    ifHot.setFieldValue("YES", "SUSTAIN");
    ifHot.initSvg();
    ifHot.render();
    onTemp.getInput("DO").connection.connect(ifHot.previousConnection);

    var nHot = workspace.newBlock("thesada_notify_temp");
    nHot.setFieldValue("Overheat!", "SUFFIX");
    nHot.initSvg();
    nHot.render();
    ifHot.getInput("DO").connection.connect(nHot.previousConnection);

    var onBatt = workspace.newBlock("thesada_on_sensor");
    onBatt.setFieldValue("battery", "EVENT");
    onBatt.initSvg();
    onBatt.render();
    onTemp.nextConnection.connect(onBatt.previousConnection);

    var ifBatt = workspace.newBlock("thesada_if_battery");
    ifBatt.setFieldValue("20", "PCT");
    ifBatt.initSvg();
    ifBatt.render();
    onBatt.getInput("DO").connection.connect(ifBatt.previousConnection);

    var nBatt = workspace.newBlock("thesada_notify");
    nBatt.setFieldValue("Battery low", "MSG");
    nBatt.initSvg();
    nBatt.render();
    ifBatt.getInput("DO").connection.connect(nBatt.previousConnection);
  }

  function init(opts) {
    defineBlocks();
    var workspace = Blockly.inject(opts.workspaceEl, {
      toolbox: opts.toolboxEl,
      media: opts.mediaPath,
      trashcan: true,
      scrollbars: true,
      grid: { spacing: 20, length: 3, colour: "#ccc", snap: true },
      zoom: { controls: true, wheel: true, startScale: 0.9 },
    });
    // Caller decides seed vs restore; default remains seed for empty pages.
    if (opts.seed === true || (opts.seed !== false && !opts.savedState)) {
      seedWorkspace(workspace);
    } else if (opts.savedState) {
      loadWorkspace(workspace, opts.savedState);
    }
    if (typeof Blockly !== "undefined" && Blockly.svgResize) {
      setTimeout(function () {
        Blockly.svgResize(workspace);
      }, 0);
    }
    return workspace;
  }

  function generateLua(workspace) {
    var tops = workspace.getTopBlocks(true);
    var out = [];
    for (var i = 0; i < tops.length; i++) {
      if (tops[i].type !== "thesada_rules_root") continue;
      var code = Blockly.Lua.blockToCode(tops[i]);
      if (Array.isArray(code)) code = code[0];
      if (code) out.push(code);
    }
    return (PREAMBLE + out.join("\n")).replace(/\n+$/, "\n");
  }

  function serializeWorkspace(workspace) {
    return Blockly.serialization.workspaces.save(workspace);
  }

  function loadWorkspace(workspace, state) {
    workspace.clear();
    Blockly.serialization.workspaces.load(state, workspace);
  }

  return {
    init: init,
    generateLua: generateLua,
    seedWorkspace: seedWorkspace,
    serializeWorkspace: serializeWorkspace,
    loadWorkspace: loadWorkspace,
  };
})();
